-- Rebuild Medina Book 4 lesson 11 strictly from the supplied Arabic sharh.
-- Canonical PDF pages: 45-50. DOC text was used only for extraction and checked against the PDF.
begin;

do $migration$
declare
  existing_count integer;
begin
  select count(*) into existing_count
  from public.rules
  where course_name = 'Мединский курс (Том 4)' and lesson_number = '11';
  if existing_count = 4 then
    insert into public.rules (course_name, lesson_number, title, content, sort_order, rule_kind, summary, rule_ar) values
      ('Мединский курс (Том 4)', '11', '__book4_lesson11_hayah__', '', 5, 'rule', '', null),
      ('Мединский курс (Том 4)', '11', '__book4_lesson11_mimi__', '', 6, 'rule', '', null),
      ('Мединский курс (Том 4)', '11', '__book4_lesson11_irab__', '', 7, 'rule', '', null);
  elsif existing_count <> 7 then
    raise exception 'Expected 4 legacy or 7 rebuilt Book 4 lesson 11 rules, found %', existing_count;
  end if;
end $migration$;

with incoming(sort_order, title, content, summary, rule_ar) as (
  values
    (1, 'الْمَفْعُولُ الْمُطْلَقُ وَأَنْوَاعُهُ (абсолютное дополнение и его виды)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-object" dir="rtl" lang="ar">الْمَفْعُولُ الْمُطْلَقُ مَصْدَرٌ يُذْكَرُ بَعْدَ فِعْلٍ مِنْ لَفْظِهِ، وَهُوَ أَرْبَعَةُ أَنْوَاعٍ: مُؤَكِّدٌ لِفِعْلِهِ، وَمُبَيِّنٌ لِنَوْعِ الْفِعْلِ، وَمُبَيِّنٌ لِعَدَدِ الْفِعْلِ، وَمَصْدَرٌ نَائِبٌ عَنْ فِعْلِهِ.</span><p class="rule-study-text">Абсолютное дополнение — масдар, употреблённый после однокоренного глагола. Он усиливает действие, поясняет его вид, указывает число повторений либо заменяет свой глагол.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Четыре вида</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">النَّوْعُ</span><span class="rule-table-ru">вид</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْوَظِيفَةُ</span><span class="rule-table-ru">назначение</span></th><th><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">الْأَمْثِلَةُ</span><span class="rule-table-ru">примеры и перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">مُؤَكِّدٌ لِفِعْلِهِ</span><span class="rule-table-ru">усиливающий свой глагол</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">تَوْكِيدُ مَعْنَى الْفِعْلِ</span><span class="rule-table-ru">подтверждает и усиливает значение действия</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">فَهِمْتُ الدَّرْسَ فَهْمًا؛ أَكَلْتُ أَكْلًا؛ نِمْتُ نَوْمًا.</span><span class="rule-table-ru">Я понял урок; я поел; я поспал — масдар усиливает каждый глагол.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">مُبَيِّنٌ لِنَوْعِ الْفِعْلِ</span><span class="rule-table-ru">поясняющий вид действия</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">بَيَانُ صِفَةِ الْفِعْلِ أَوْ نَوْعِهِ</span><span class="rule-table-ru">указывает качество или разновидность действия</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">فَهِمْتُ الدَّرْسَ فَهْمًا جَيِّدًا؛ أَكَلْتُ أَكْلَ الْجَائِعِ؛ فَهِمْتُ الْمَسْأَلَةَ فَهْمَ الْعُلَمَاءِ.</span><span class="rule-table-ru">Я хорошо понял урок; ел как голодный; понял вопрос пониманием учёных.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">مُبَيِّنٌ لِعَدَدِ الْفِعْلِ</span><span class="rule-table-ru">поясняющий число действий</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">بَيَانُ عَدَدِ مَرَّاتِ الْفِعْلِ</span><span class="rule-table-ru">указывает количество повторений</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">طَبَعْتُ الْكِتَابَ طَبْعَةً أَوْ طَبْعَتَيْنِ أَوْ طَبَعَاتٍ؛ سَجَدْتُ لِلَّهِ سَجْدَةً أَوْ سَجْدَتَيْنِ أَوْ سَجَدَاتٍ.</span><span class="rule-table-ru">Я напечатал книгу один, два или несколько раз; совершил один, два или несколько земных поклонов.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">مَصْدَرٌ نَائِبٌ عَنْ فِعْلِهِ</span><span class="rule-table-ru">масдар, заменяющий свой глагол</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">حَذْفُ الْفِعْلِ وَإِقَامَةُ الْمَصْدَرِ مَقَامَهُ</span><span class="rule-table-ru">глагол удалён, а масдар занимает его место</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">مَهْلًا، وَصَبْرًا، وَحَمْدًا، وَشُكْرًا، وَسُبْحَانَ اللَّهِ، وَمَعَاذَ اللَّهِ، وَلَبَّيْكَ، وَسَمْعًا وَطَاعَةً.</span><span class="rule-table-ru">Не спеши; терпение; хвала; благодарность; пречист Аллах; упаси Аллах; вот я перед Тобой; слушаюсь и повинуюсь.</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Коранические примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-quran"><span class="rule-example-ar ar-tone-quran rule-quran-ar" dir="rtl" lang="ar">﴿وَكَلَّمَ ٱللَّهُ مُوسَىٰ تَكۡلِيمٗا﴾</span><span class="rule-example-ru">И Аллах говорил с Мусой непосредственной речью — масдар усиливает глагол.</span></div><div class="rule-example-card rule-term-quran"><span class="rule-example-ar ar-tone-quran rule-quran-ar" dir="rtl" lang="ar">﴿وَتُحِبُّونَ ٱلۡمَالَ حُبّٗا جَمّٗا﴾</span><span class="rule-example-ru">И вы любите богатство сильной любовью — описание поясняет вид любви.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Условие для пояснения вида</span><div class="rule-example-list"><div class="rule-example-card rule-term-structure"><span class="rule-example-ar ar-tone-structure" dir="rtl" lang="ar">لَا بُدَّ أَنْ يَكُونَ بَعْدَ الْمَصْدَرِ صِفَةٌ أَوْ مُضَافٌ إِلَيْهِ.</span><span class="rule-example-ru">После масдара, поясняющего вид действия, обязательно стоит либо определение, либо مُضَافٌ إِلَيْهِ.</span></div></div></div></div>', 'Абсолютное дополнение — масдар, употреблённый после однокоренного глагола. Он усиливает действие, поясняет его вид, указывает число повторений либо заменяет свой глагол.', 'الْمَفْعُولُ الْمُطْلَقُ مَصْدَرٌ يُذْكَرُ بَعْدَ فِعْلٍ مِنْ لَفْظِهِ، وَهُوَ أَرْبَعَةُ أَنْوَاعٍ: مُؤَكِّدٌ لِفِعْلِهِ، وَمُبَيِّنٌ لِنَوْعِ الْفِعْلِ، وَمُبَيِّنٌ لِعَدَدِ الْفِعْلِ، وَمَصْدَرٌ نَائِبٌ عَنْ فِعْلِهِ.'),
    (2, 'حَذْفُ عَامِلِ الْمَفْعُولِ الْمُطْلَقِ (удаление управляющего слова абсолютного дополнения)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-verb" dir="rtl" lang="ar">لَا يَجُوزُ حَذْفُ عَامِلِ الْمَفْعُولِ الْمُطْلَقِ الْمُؤَكِّدِ لِفِعْلِهِ؛ لِأَنَّ الْمَصْدَرَ جِيءَ بِهِ لِتَوْكِيدِ مَعْنَى عَامِلِهِ وَتَقْوِيَتِهِ. وَيَجُوزُ حَذْفُ عَامِلِ الْمُبَيِّنِ لِلنَّوْعِ أَوِ الْعَدَدِ بِشَرْطِ وُجُودِ دَلِيلٍ عَلَيْهِ.</span><p class="rule-study-text">Управляющий глагол нельзя удалять при усиливающем абсолютном дополнении. При пояснении вида или числа его можно опустить, если контекст ясно указывает на удалённый глагол.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Когда удаление возможно</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">نَوْعُ الْمَفْعُولِ الْمُطْلَقِ</span><span class="rule-table-ru">вид абсолютного дополнения</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">حُكْمُ حَذْفِ الْعَامِلِ</span><span class="rule-table-ru">правило удаления</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">السَّبَبُ</span><span class="rule-table-ru">основание</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">الْمُؤَكِّدُ لِفِعْلِهِ</span><span class="rule-table-ru">усиливающий свой глагол</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">لَا يَجُوزُ</span><span class="rule-table-ru">удаление не допускается</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">لِأَنَّهُ جِيءَ بِهِ لِتَوْكِيدِ عَامِلِهِ</span><span class="rule-table-ru">масдар введён именно для усиления управляющего слова</span></td></tr><tr><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">الْمُبَيِّنُ لِلنَّوْعِ أَوِ الْعَدَدِ</span><span class="rule-table-ru">поясняющий вид или число</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">يَجُوزُ بِشَرْطِ الدَّلَالَةِ عَلَيْهِ</span><span class="rule-table-ru">допускается при наличии указания</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">يُفْهَمُ الْعَامِلُ مِنَ السِّيَاقِ</span><span class="rule-table-ru">управляющий глагол восстанавливается из контекста</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Все примеры шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-object"><span class="rule-example-ar ar-tone-object" dir="rtl" lang="ar">قُدُومًا مُبَارَكًا؛ أَيْ: قَدِمْتَ قُدُومًا مُبَارَكًا.</span><span class="rule-example-ru">С благословенным прибытием; то есть: ты прибыл благословенным прибытием.</span></div><div class="rule-example-card rule-term-object"><span class="rule-example-ar ar-tone-object" dir="rtl" lang="ar">حَجًّا مَبْرُورًا؛ أَيْ: حَجَجْتَ حَجًّا مَبْرُورًا.</span><span class="rule-example-ru">Принятого хаджа; то есть: ты совершил принятый хадж.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">كَمْ قِرَاءَةً قَرَأْتَ الدَّرْسَ؟ قِرَاءَتَيْنِ؛ أَيْ: قَرَأْتُهُ قِرَاءَتَيْنِ.</span><span class="rule-example-ru">Сколько раз ты прочитал урок? Два раза; то есть: я прочитал его дважды.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">كَمْ سَجْدَةً لِلَّهِ سَجَدْتَ؟ سَجَدَاتٍ.</span><span class="rule-example-ru">Сколько земных поклонов Аллаху ты совершил? Несколько земных поклонов.</span></div></div></div></div>', 'Управляющий глагол нельзя удалять при усиливающем абсолютном дополнении. При пояснении вида или числа его можно опустить, если контекст ясно указывает на удалённый глагол.', 'لَا يَجُوزُ حَذْفُ عَامِلِ الْمَفْعُولِ الْمُطْلَقِ الْمُؤَكِّدِ لِفِعْلِهِ؛ لِأَنَّ الْمَصْدَرَ جِيءَ بِهِ لِتَوْكِيدِ مَعْنَى عَامِلِهِ وَتَقْوِيَتِهِ. وَيَجُوزُ حَذْفُ عَامِلِ الْمُبَيِّنِ لِلنَّوْعِ أَوِ الْعَدَدِ بِشَرْطِ وُجُودِ دَلِيلٍ عَلَيْهِ.'),
    (3, 'النَّائِبُ عَنِ الْمَصْدَرِ (заместитель масдара)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-object" dir="rtl" lang="ar">يَنُوبُ عَنِ الْمَصْدَرِ مَا يَدُلُّ عَلَيْهِ، فَيُعْرَبُ مَفْعُولًا مُطْلَقًا نَائِبًا عَنِ الْمَصْدَرِ. وَمِنْ نَوَائِبِهِ: أَلْفَاظُ كُلٍّ وَبَعْضٍ وَأَيٍّ وَكَمْ إِذَا أُضِيفَتْ إِلَى الْمَصْدَرِ، وَصِفَةُ الْمَصْدَرِ، وَعَدَدُهُ، وَمَصْدَرٌ يُلَاقِيهِ فِي الِاشْتِقَاقِ، وَاسْمُ الْمَصْدَرِ، وَاسْمُ الْإِشَارَةِ، وَالضَّمِيرُ الْعَائِدُ إِلَيْهِ، وَمُرَادِفُهُ.</span><p class="rule-study-text">Любое слово, которое указывает на подразумеваемый масдар, может заместить его и разбирается как абсолютное дополнение — заместитель масдара. Шарх перечисляет восемь таких типов.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Заместители 1–4</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">النَّائِبُ</span><span class="rule-table-ru">тип заместителя</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْأَمْثِلَةُ</span><span class="rule-table-ru">примеры</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْمَعْنَى وَالْبَيَانُ</span><span class="rule-table-ru">перевод и пояснение</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">كُلٌّ، وَبَعْضٌ، وَأَيٌّ، وَكَمْ</span><span class="rule-table-ru">слова كُلٌّ, بَعْضٌ, أَيٌّ и كَمْ</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">فَهِمْتُ الدَّرْسَ كُلَّ الْفَهْمِ؛ فَهِمْتُ الدَّرْسَ بَعْضَ الْفَهْمِ؛ أَيَّ فَهْمٍ فَهِمْتَ الدَّرْسَ؟ كَمْ قِرَاءَةً قَرَأْتَ الدَّرْسَ؟</span><span class="rule-table-ru">Я понял урок полностью; понял частично; каким пониманием ты понял урок? сколько раз прочитал?</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">مُضَافَةٌ إِلَى الْمَصْدَرِ</span><span class="rule-table-ru">эти слова присоединяются к масдару</span></td></tr><tr><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">صِفَةُ الْمَصْدَرِ</span><span class="rule-table-ru">определение масдара</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">فَهِمْتُ الدَّرْسَ جَيِّدًا؛ أَيْ: فَهْمًا جَيِّدًا. سَاعَدْتُهُ أَحْسَنَ الْمُسَاعَدَةِ.</span><span class="rule-table-ru">Я хорошо понял урок, то есть хорошим пониманием; помог ему наилучшей помощью.</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الصِّفَةُ تَنُوبُ عَنِ الْمَصْدَرِ</span><span class="rule-table-ru">определение занимает место масдара</span></td></tr><tr><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">عَدَدُ الْمَصْدَرِ</span><span class="rule-table-ru">число масдара</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">زُرْتُكَ ثَلَاثَ زِيَارَاتٍ؛ ضَرَبْتُهُ عِشْرِينَ ضَرْبَةً.</span><span class="rule-table-ru">Я посетил тебя три раза; ударил его двадцать раз.</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْعَدَدُ يَدُلُّ عَلَى تَكَرُّرِ الْفِعْلِ</span><span class="rule-table-ru">числительное показывает количество действий</span></td></tr><tr><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">مَصْدَرٌ يُلَاقِيهِ فِي الِاشْتِقَاقِ</span><span class="rule-table-ru">родственный по словообразованию масдар</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">تَبَسَّمْتُ ابْتِسَامًا؛ أُحِبُّ اللَّهَ حُبًّا جَمًّا.</span><span class="rule-table-ru">Я улыбнулся улыбкой; люблю Аллаха сильной любовью.</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">تَبَسَّمَ وَابْتِسَامٌ مُشْتَقَّانِ مِنْ بَسَمَ</span><span class="rule-table-ru">تَبَسَّمَ и اِبْتِسَامٌ происходят от корня глагола بَسَمَ</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Коранические примеры к числу и родству</span><div class="rule-example-list"><div class="rule-example-card rule-term-quran"><span class="rule-example-ar ar-tone-quran rule-quran-ar" dir="rtl" lang="ar">﴿فَٱجۡلِدُواْ كُلَّ وَٰحِدٖ مِّنۡهُمَا مِاْئَةَ جَلۡدَةٖ﴾</span><span class="rule-example-ru">Высеките каждого из них сотней ударов — числительное замещает масдар.</span></div><div class="rule-example-card rule-term-quran"><span class="rule-example-ar ar-tone-quran rule-quran-ar" dir="rtl" lang="ar">﴿وَتُحِبُّونَ ٱلۡمَالَ حُبّٗا جَمّٗا﴾</span><span class="rule-example-ru">И вы любите богатство сильной любовью — حُبًّا родствен глаголу تُحِبُّونَ.</span></div><div class="rule-example-card rule-term-quran"><span class="rule-example-ar ar-tone-quran rule-quran-ar" dir="rtl" lang="ar">﴿وَرَتِّلِ ٱلۡقُرۡءَانَ تَرۡتِيلًا﴾</span><span class="rule-example-ru">И читай Коран размеренным чтением — تَرْتِيلًا родствен глаголу رَتِّلْ.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Заместители 5–8</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">النَّائِبُ</span><span class="rule-table-ru">тип заместителя</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْأَمْثِلَةُ</span><span class="rule-table-ru">примеры</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْمَعْنَى وَالْبَيَانُ</span><span class="rule-table-ru">перевод и пояснение</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">اسْمُ الْمَصْدَرِ</span><span class="rule-table-ru">имя масдара</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">كَلَّمْتُهُ كَلَامًا؛ صَلَّيْتُ صَلَاةً؛ قَبَّلْتُ ابْنِي قُبْلَةً؛ اِغْتَسَلْتُ غُسْلًا؛ أَعْطَيْتُهُ عَطَاءً.</span><span class="rule-table-ru">Я говорил с ним; совершил молитву; поцеловал сына; искупался; дал ему дар.</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">حُرُوفُهُ أَقَلُّ مِنْ حُرُوفِ الْمَصْدَرِ الْأَصْلِيِّ</span><span class="rule-table-ru">передаёт событие, но букв меньше, чем в исходном масдаре</span></td></tr><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">اسْمُ الْإِشَارَةِ</span><span class="rule-table-ru">указательное местоимение</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">أَتُعَامِلُهُ تِلْكَ الْمُعَامَلَةَ؟ ضَرَبْتُهُ هَذَا الضَّرْبَ لِأَنَّهُ كَسْلَانُ.</span><span class="rule-table-ru">Неужели ты обращаешься с ним таким образом? Я ударил его таким ударом, потому что он ленив.</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">اسْمُ الْإِشَارَةِ يَدُلُّ عَلَى الْمَصْدَرِ</span><span class="rule-table-ru">указательное местоимение отсылает к масдару</span></td></tr><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">الضَّمِيرُ الْعَائِدُ إِلَى الْمَصْدَرِ</span><span class="rule-table-ru">местоимение, возвращающееся к масдару</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">قَرَأْتُ قِرَاءَةً لَمْ يَقْرَأْهَا غَيْرِي.</span><span class="rule-table-ru">Я прочитал таким чтением, каким не читал никто другой.</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">هَا تَعُودُ إِلَى قِرَاءَةً</span><span class="rule-table-ru">местоимение هَا возвращается к слову قِرَاءَةً</span></td></tr><tr><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">مُرَادِفُ الْمَصْدَرِ</span><span class="rule-table-ru">синоним масдара</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">قُمْتُ وُقُوفًا؛ جَلَسْتُ قُعُودًا؛ فَرِحْتُ جَذَلًا؛ عِشْتُ حَيَاةً سَعِيدَةً.</span><span class="rule-table-ru">Я встал; сел; обрадовался; прожил счастливую жизнь — употреблены близкие по смыслу масдары.</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">الْمُرَادِفُ مُمَاثِلٌ لِلْمَصْدَرِ فِي الْمَعْنَى</span><span class="rule-table-ru">синоним совпадает с подразумеваемым масдаром по смыслу</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Коранический пример к местоимению</span><div class="rule-example-list"><div class="rule-example-card rule-term-quran"><span class="rule-example-ar ar-tone-quran rule-quran-ar" dir="rtl" lang="ar">﴿فَإِنِّيٓ أُعَذِّبُهُۥ عَذَابٗا لَّآ أُعَذِّبُهُۥٓ أَحَدٗا مِّنَ ٱلۡعَٰلَمِينَ﴾</span><span class="rule-example-ru">Я подвергну его наказанию, которому не подвергал никого из миров: هُ в أُعَذِّبُهُ возвращается к عَذَابًا.</span></div></div></div></div>', 'Любое слово, которое указывает на подразумеваемый масдар, может заместить его и разбирается как абсолютное дополнение — заместитель масдара. Шарх перечисляет восемь таких типов.', 'يَنُوبُ عَنِ الْمَصْدَرِ مَا يَدُلُّ عَلَيْهِ، فَيُعْرَبُ مَفْعُولًا مُطْلَقًا نَائِبًا عَنِ الْمَصْدَرِ. وَمِنْ نَوَائِبِهِ: أَلْفَاظُ كُلٍّ وَبَعْضٍ وَأَيٍّ وَكَمْ إِذَا أُضِيفَتْ إِلَى الْمَصْدَرِ، وَصِفَةُ الْمَصْدَرِ، وَعَدَدُهُ، وَمَصْدَرٌ يُلَاقِيهِ فِي الِاشْتِقَاقِ، وَاسْمُ الْمَصْدَرِ، وَاسْمُ الْإِشَارَةِ، وَالضَّمِيرُ الْعَائِدُ إِلَيْهِ، وَمُرَادِفُهُ.'),
    (4, 'مَصْدَرُ الْمَرَّةِ (масдар однократности)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-structure" dir="rtl" lang="ar">مَصْدَرُ الْمَرَّةِ يُذْكَرُ لِبَيَانِ عَدَدِ الْفِعْلِ. يُصَاغُ مِنَ الثُّلَاثِيِّ الْمُجَرَّدِ عَلَى وَزْنِ فَعْلَةٍ، وَمِنْ غَيْرِ الثُّلَاثِيِّ بِزِيَادَةِ تَاءٍ فِي آخِرِ مَصْدَرِهِ الْأَصْلِيِّ. فَإِنْ كَانَ الْمَصْدَرُ مَخْتُومًا بِالتَّاءِ أَصْلًا، ذُكِرَ بَعْدَهُ مَا يَدُلُّ عَلَى الْعَدَدِ، كَكَلِمَةِ وَاحِدَةٍ.</span><p class="rule-study-text">Масдар однократности показывает число совершений действия. От простого трёхбуквенного глагола он строится по модели فَعْلَةٌ, а от остальных — добавлением ت к исходному масдару. Если ت уже входит в исходную форму, число выражается отдельным словом.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Образование формы</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">نَوْعُ الْفِعْلِ</span><span class="rule-table-ru">тип глагола</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الصِّيغَةُ</span><span class="rule-table-ru">способ образования</span></th><th><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">الْأَمْثِلَةُ</span><span class="rule-table-ru">примеры и перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">الثُّلَاثِيُّ الْمُجَرَّدُ</span><span class="rule-table-ru">простой трёхбуквенный</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">فَعْلَةٌ</span><span class="rule-table-ru">модель однократности</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">سَجْدَةٌ، رَكْعَةٌ، ضَرْبَةٌ، أَكْلَةٌ</span><span class="rule-table-ru">один земной поклон; один поясной поклон; один удар; один приём пищи</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">غَيْرُ الثُّلَاثِيِّ الْمُجَرَّدِ</span><span class="rule-table-ru">не простой трёхбуквенный</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">زِيَادَةُ تَاءٍ فِي آخِرِ الْمَصْدَرِ</span><span class="rule-table-ru">добавление ت в конце масдара</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">كَبَّرَ ← تَكْبِيرٌ ← تَكْبِيرَةٌ؛ سَلَّمَ ← تَسْلِيمٌ ← تَسْلِيمَةٌ</span><span class="rule-table-ru">произнёс такбир → один такбир; приветствовал → одно приветствие</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَصْدَرُ الْمَخْتُومُ بِالتَّاءِ أَصْلًا</span><span class="rule-table-ru">исходный масдар уже оканчивается на ت</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">ذِكْرُ مَا يَدُلُّ عَلَى الْعَدَدِ</span><span class="rule-table-ru">добавляется слово количества</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">تَرْجَمَةً وَاحِدَةً؛ اسْتِرَاحَةً وَاحِدَةً؛ إِقَامَةً وَاحِدَةً</span><span class="rule-table-ru">один перевод; один отдых; одно пребывание</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры в предложениях</span><div class="rule-example-list"><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">سَجَدْتُ لِلَّهِ سَجْدَةً، وَرَكَعْتُ رَكْعَةً.</span><span class="rule-example-ru">Я совершил Аллаху один земной поклон и один поясной поклон.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">تَرْجَمْتُ الْكِتَابَ تَرْجَمَةً وَاحِدَةً؛ اِسْتَرَحْتُ اسْتِرَاحَةً وَاحِدَةً؛ أَقَمْتُ إِقَامَةً وَاحِدَةً.</span><span class="rule-example-ru">Я перевёл книгу один раз; отдохнул один раз; пробыл один раз.</span></div></div></div></div>', 'Масдар однократности показывает число совершений действия. От простого трёхбуквенного глагола он строится по модели فَعْلَةٌ, а от остальных — добавлением ت к исходному масдару. Если ت уже входит в исходную форму, число выражается отдельным словом.', 'مَصْدَرُ الْمَرَّةِ يُذْكَرُ لِبَيَانِ عَدَدِ الْفِعْلِ. يُصَاغُ مِنَ الثُّلَاثِيِّ الْمُجَرَّدِ عَلَى وَزْنِ فَعْلَةٍ، وَمِنْ غَيْرِ الثُّلَاثِيِّ بِزِيَادَةِ تَاءٍ فِي آخِرِ مَصْدَرِهِ الْأَصْلِيِّ. فَإِنْ كَانَ الْمَصْدَرُ مَخْتُومًا بِالتَّاءِ أَصْلًا، ذُكِرَ بَعْدَهُ مَا يَدُلُّ عَلَى الْعَدَدِ، كَكَلِمَةِ وَاحِدَةٍ.'),
    (5, 'مَصْدَرُ الْهَيْئَةِ (масдар образа действия)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-structure" dir="rtl" lang="ar">مَصْدَرُ الْهَيْئَةِ يُذْكَرُ لِبَيَانِ هَيْئَةِ الْفِعْلِ وَصِفَتِهِ، وَيُصَاغُ مِنَ الثُّلَاثِيِّ الْمُجَرَّدِ عَلَى وَزْنِ فِعْلَةٍ. وَلَا يُصَاغُ مِنْ غَيْرِ الثُّلَاثِيِّ الْمُجَرَّدِ.</span><p class="rule-study-text">Масдар образа действия показывает, каким образом или с каким качеством совершено действие. Он образуется только от простого трёхбуквенного глагола по модели فِعْلَةٌ.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Форма и ограничение</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar ar-tone-structure" dir="rtl" lang="ar">فِعْلَةٌ</span><span class="rule-term-ru">модель масдара образа действия</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar ar-tone-structure" dir="rtl" lang="ar">إِكْلَةٌ، مِشْيَةٌ، جِلْسَةٌ، قِتْلَةٌ</span><span class="rule-term-ru">манера еды; походка; манера сидения; способ убийства</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar ar-tone-verb" dir="rtl" lang="ar">لَا يُصَاغُ مِنْ غَيْرِ الثُّلَاثِيِّ الْمُجَرَّدِ</span><span class="rule-term-ru">не образуется от иных глаголов, кроме простых трёхбуквенных</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Все примеры шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">أَكَلْتُ إِكْلَةَ الْجَائِعِ.</span><span class="rule-example-ru">Я ел так, как ест голодный.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">مَشَيْتُ مِشْيَةَ الْأَسَدِ.</span><span class="rule-example-ru">Я шёл походкой льва.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">مَاتَ مِيتَةً حَسَنَةً.</span><span class="rule-example-ru">Он умер хорошей смертью.</span></div><div class="rule-example-card rule-term-quran"><span class="rule-example-ar ar-tone-quran rule-quran-ar" dir="rtl" lang="ar">﴿فَهُوَ فِي عِيشَةٖ رَّاضِيَةٖ﴾</span><span class="rule-example-ru">Он будет в приятной жизни — رَاضِيَةٍ описывает образ и качество жизни.</span></div></div></div></div>', 'Масдар образа действия показывает, каким образом или с каким качеством совершено действие. Он образуется только от простого трёхбуквенного глагола по модели فِعْلَةٌ.', 'مَصْدَرُ الْهَيْئَةِ يُذْكَرُ لِبَيَانِ هَيْئَةِ الْفِعْلِ وَصِفَتِهِ، وَيُصَاغُ مِنَ الثُّلَاثِيِّ الْمُجَرَّدِ عَلَى وَزْنِ فِعْلَةٍ. وَلَا يُصَاغُ مِنْ غَيْرِ الثُّلَاثِيِّ الْمُجَرَّدِ.'),
    (6, 'الْمَصْدَرُ الْمِيمِيُّ (масдар, начинающийся с добавочной م)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-structure" dir="rtl" lang="ar">الْمَصْدَرُ الْمِيمِيُّ مَا كَانَ فِي أَوَّلِهِ مِيمٌ زَائِدَةٌ. يُصَاغُ مِنَ الثُّلَاثِيِّ الْمُجَرَّدِ عَلَى مَفْعِلٍ إِذَا كَانَ مُعْتَلَّ الْأَوَّلِ صَحِيحَ الْآخِرِ، وَعَلَى مَفْعَلٍ إِذَا لَمْ يَكُنْ كَذَلِكَ. وَيُصَاغُ مِنْ غَيْرِ الثُّلَاثِيِّ عَلَى زِنَةِ اسْمِ الْمَفْعُولِ: بِمِيمٍ مَضْمُومَةٍ وَفَتْحِ مَا قَبْلَ الْآخِرِ.</span><p class="rule-study-text">Мимический масдар начинается с добавочной م. У простого трёхбуквенного глагола используются модели مَفْعِلٌ и مَفْعَلٌ по состоянию первой и последней коренной. У остальных глаголов форма совпадает с моделью страдательного причастия.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Простой трёхбуквенный глагол</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْوَزْنُ</span><span class="rule-table-ru">модель</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الشَّرْطُ</span><span class="rule-table-ru">условие</span></th><th><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">الْأَمْثِلَةُ</span><span class="rule-table-ru">примеры и перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَفْعِلٌ</span><span class="rule-table-ru">модель с касрой</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">مُعْتَلُّ الْأَوَّلِ صَحِيحُ الْآخِرِ</span><span class="rule-table-ru">первая коренная слабая, последняя сильная</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">وَعَدَ ← مَوْعِدٌ؛ وَقَفَ ← مَوْقِفٌ؛ وَضَعَ ← مَوْضِعٌ</span><span class="rule-table-ru">обещал → обещание/срок; стоял → стояние/позиция; положил → место</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَفْعَلٌ</span><span class="rule-table-ru">модель с фатхой</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">إِذَا لَمْ يَكُنْ مِثَالًا</span><span class="rule-table-ru">если глагол не является слабым в начале</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">ضَرَبَ ← مَضْرَبٌ؛ نَهَجَ ← مَنْهَجٌ؛ نَجَا ← مَنْجَاةٌ؛ قَالَ ← مَقَالَةٌ</span><span class="rule-table-ru">ударил → место/способ удара; следовал → путь; спасся → спасение; сказал → высказывание</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры трёхбуквенных форм</span><div class="rule-example-list"><div class="rule-example-card rule-term-structure"><span class="rule-example-ar ar-tone-structure" dir="rtl" lang="ar">مَوْعِدُ اللَّهِ حَقٌّ؛ أَيْ: وَعْدُ اللَّهِ حَقٌّ.</span><span class="rule-example-ru">Обещание Аллаха истинно; то есть обещанное Аллахом истинно.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar ar-tone-structure" dir="rtl" lang="ar">مَوْقِفُكَ مَعِي كَانَ عَظِيمًا؛ أَيْ: وُقُوفُكَ مَعِي.</span><span class="rule-example-ru">Твоя поддержка меня была великой; то есть твоё стояние со мной.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">نَهَجْتُ مَنْهَجَ الصَّالِحِينَ، وَسَلَكْتُ مَسْلَكَهُمْ.</span><span class="rule-example-ru">Я последовал путём праведных и шёл их дорогой.</span></div><div class="rule-example-card rule-term-predicate"><span class="rule-example-ar ar-tone-predicate" dir="rtl" lang="ar">الصِّدْقُ مَنْجَاةٌ، وَالْكَذِبُ مَفْسَدَةٌ.</span><span class="rule-example-ru">Правдивость — спасение, а ложь — погибель.</span></div><div class="rule-example-card rule-term-quran"><span class="rule-example-ar ar-tone-quran rule-quran-ar" dir="rtl" lang="ar">﴿وَمَا كَانَ ٱسۡتِغۡفَارُ إِبۡرَٰهِيمَ لِأَبِيهِ إِلَّا عَن مَّوۡعِدَةٖ وَعَدَهَآ إِيَّاهُ﴾</span><span class="rule-example-ru">Просьба Ибрахима о прощении для отца была лишь по обещанию, которое он дал ему — مَوْعِدَةٍ является мимическим масдаром.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Формы от нетрёхбуквенных глаголов</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْقَاعِدَةُ</span><span class="rule-table-ru">правило формы</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْأَمْثِلَةُ</span><span class="rule-table-ru">примеры</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْمَعْنَى بِالرُّوسِيَّةِ</span><span class="rule-table-ru">русский смысл</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مِيمٌ مَضْمُومَةٌ وَفَتْحُ مَا قَبْلَ الْآخِرِ</span><span class="rule-table-ru">م с даммой и фатха перед последней коренной</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مُنْقَلَبٌ، مُمَزَّقٌ، مُخْتَلَفٌ، مُجْتَمَعٌ، مُسْتَقًى، مُدْخَلٌ، مُخْرَجٌ</span><span class="rule-table-ru">возвращение; разрыв; различие; собрание; орошение; вход; выход</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">عَلَى زِنَةِ اسْمِ الْمَفْعُولِ</span><span class="rule-table-ru">по форме страдательного причастия</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Предложения и аяты</span><div class="rule-example-list"><div class="rule-example-card rule-term-structure"><span class="rule-example-ar ar-tone-structure" dir="rtl" lang="ar">مُجْتَمَعُ الطُّلَّابِ خَيْرٌ؛ أَيْ: اجْتِمَاعُهُمْ.</span><span class="rule-example-ru">Собрание студентов — благо; то есть их совместное пребывание.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar ar-tone-structure" dir="rtl" lang="ar">مُسْتَقَى الزَّرْعِ يُحْيِيهِ؛ أَيْ: سَقْيُ الزَّرْعِ يُحْيِيهِ.</span><span class="rule-example-ru">Орошение посева оживляет его; то есть полив оживляет посев.</span></div><div class="rule-example-card rule-term-quran"><span class="rule-example-ar ar-tone-quran rule-quran-ar" dir="rtl" lang="ar">﴿وَسَيَعۡلَمُ ٱلَّذِينَ ظَلَمُوٓاْ أَيَّ مُنقَلَبٖ يَنقَلِبُونَ﴾</span><span class="rule-example-ru">И узнают несправедливые, каким возвращением они вернутся.</span></div><div class="rule-example-card rule-term-quran"><span class="rule-example-ar ar-tone-quran rule-quran-ar" dir="rtl" lang="ar">﴿وَمَزَّقۡنَٰهُمۡ كُلَّ مُمَزَّقٍ﴾</span><span class="rule-example-ru">И Мы полностью рассеяли их.</span></div></div></div></div>', 'Мимический масдар начинается с добавочной م. У простого трёхбуквенного глагола используются модели مَفْعِلٌ и مَفْعَلٌ по состоянию первой и последней коренной. У остальных глаголов форма совпадает с моделью страдательного причастия.', 'الْمَصْدَرُ الْمِيمِيُّ مَا كَانَ فِي أَوَّلِهِ مِيمٌ زَائِدَةٌ. يُصَاغُ مِنَ الثُّلَاثِيِّ الْمُجَرَّدِ عَلَى مَفْعِلٍ إِذَا كَانَ مُعْتَلَّ الْأَوَّلِ صَحِيحَ الْآخِرِ، وَعَلَى مَفْعَلٍ إِذَا لَمْ يَكُنْ كَذَلِكَ. وَيُصَاغُ مِنْ غَيْرِ الثُّلَاثِيِّ عَلَى زِنَةِ اسْمِ الْمَفْعُولِ: بِمِيمٍ مَضْمُومَةٍ وَفَتْحِ مَا قَبْلَ الْآخِرِ.'),
    (7, 'إِعْرَابُ الْمَفْعُولِ الْمُطْلَقِ وَنَوَائِبِهِ (грамматический разбор абсолютного дополнения и его заместителей)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-object" dir="rtl" lang="ar">الْمَفْعُولُ الْمُطْلَقُ وَنَائِبُهُ مَنْصُوبَانِ، وَتَخْتَلِفُ عَلَامَةُ النَّصْبِ بِحَسَبِ صِيغَةِ الْكَلِمَةِ. وَإِذَا نَابَ عَنِ الْمَصْدَرِ عَدَدٌ أَوْ صِفَةٌ أَوْ اسْمُ إِشَارَةٍ، أُعْرِبَ النَّائِبُ مَفْعُولًا مُطْلَقًا، وَأُعْرِبَ مَا يَتْبَعُهُ بِحَسَبِ مَوْقِعِهِ.</span><p class="rule-study-text">Абсолютное дополнение и его заместитель стоят в винительном падеже. Окончание зависит от формы слова, а зависимые элементы разбираются по своей функции: как различительное слово, مُضَافٌ إِلَيْهِ или بَدَلٌ.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Полный إِعْرَاب из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-object"><span class="rule-example-ar ar-tone-object" dir="rtl" lang="ar">أَكْلًا: مَفْعُولٌ مُطْلَقٌ مَنْصُوبٌ، وَعَلَامَةُ نَصْبِهِ الْفَتْحَةُ الظَّاهِرَةُ.</span><span class="rule-example-ru">أَكْلًا — абсолютное дополнение в винительном падеже; показатель — явно выраженная фатха.</span></div><div class="rule-example-card rule-term-object"><span class="rule-example-ar ar-tone-object" dir="rtl" lang="ar">ضَرْبَتَيْنِ: مَفْعُولٌ مُطْلَقٌ مَنْصُوبٌ، وَعَلَامَةُ نَصْبِهِ الْيَاءُ.</span><span class="rule-example-ru">ضَرْبَتَيْنِ — абсолютное дополнение в винительном падеже; показатель — يَاءٌ двойственного числа.</span></div><div class="rule-example-card rule-term-object"><span class="rule-example-ar ar-tone-object" dir="rtl" lang="ar">عِشْرِينَ: مَفْعُولٌ مُطْلَقٌ نَائِبٌ عَنِ الْمَصْدَرِ مَنْصُوبٌ، وَعَلَامَةُ نَصْبِهِ الْيَاءُ.</span><span class="rule-example-ru">عِشْرِينَ — абсолютное дополнение, замещающее масдар, в винительном падеже; показатель — يَاءٌ.</span></div><div class="rule-example-card rule-term-object"><span class="rule-example-ar ar-tone-object" dir="rtl" lang="ar">ضَرْبَةً: تَمْيِيزُ ذَاتٍ مَنْصُوبٌ، وَعَلَامَةُ نَصْبِهِ الْفَتْحَةُ الظَّاهِرَةُ.</span><span class="rule-example-ru">ضَرْبَةً — различительное слово при числе в винительном падеже; показатель — явно выраженная фатха.</span></div><div class="rule-example-card rule-term-predicate"><span class="rule-example-ar ar-tone-predicate" dir="rtl" lang="ar">جَيِّدًا: مَفْعُولٌ مُطْلَقٌ نَائِبٌ عَنِ الْمَصْدَرِ مَنْصُوبٌ، وَعَلَامَةُ نَصْبِهِ الْفَتْحَةُ الظَّاهِرَةُ.</span><span class="rule-example-ru">جَيِّدًا — абсолютное дополнение, замещающее масдар, в винительном падеже; показатель — явно выраженная фатха.</span></div><div class="rule-example-card rule-term-object"><span class="rule-example-ar ar-tone-object" dir="rtl" lang="ar">كُلَّ: مَفْعُولٌ مُطْلَقٌ نَائِبٌ عَنِ الْمَصْدَرِ مَنْصُوبٌ، وَعَلَامَةُ نَصْبِهِ الْفَتْحَةُ الظَّاهِرَةُ، وَهُوَ مُضَافٌ.</span><span class="rule-example-ru">كُلَّ — абсолютное дополнение, замещающее масдар, в винительном падеже; показатель — фатха; слово является مُضَافٌ.</span></div><div class="rule-example-card rule-term-object"><span class="rule-example-ar ar-tone-object" dir="rtl" lang="ar">الْفَهْمِ: مُضَافٌ إِلَيْهِ مَجْرُورٌ، وَعَلَامَةُ جَرِّهِ الْكَسْرَةُ الظَّاهِرَةُ.</span><span class="rule-example-ru">الْفَهْمِ — مُضَافٌ إِلَيْهِ в родительном падеже; показатель — явно выраженная касра.</span></div><div class="rule-example-card rule-term-object"><span class="rule-example-ar ar-tone-object" dir="rtl" lang="ar">مَهْلًا: مَفْعُولٌ مُطْلَقٌ نَائِبٌ عَنْ فِعْلِهِ مَنْصُوبٌ، وَعَلَامَةُ نَصْبِهِ الْفَتْحَةُ الظَّاهِرَةُ.</span><span class="rule-example-ru">مَهْلًا — абсолютное дополнение, заменяющее свой глагол, в винительном падеже; показатель — явно выраженная фатха.</span></div><div class="rule-example-card rule-term-subject"><span class="rule-example-ar ar-tone-subject" dir="rtl" lang="ar">هَذِهِ: اسْمُ إِشَارَةٍ مَبْنِيٌّ عَلَى الْكَسْرِ فِي مَحَلِّ نَصْبٍ مَفْعُولٍ مُطْلَقٍ نَائِبٍ عَنِ الْمَصْدَرِ.</span><span class="rule-example-ru">هَذِهِ — указательное местоимение, неизменяемое с касрой, в позиции винительного падежа как абсолютное дополнение — заместитель масдара.</span></div><div class="rule-example-card rule-term-object"><span class="rule-example-ar ar-tone-object" dir="rtl" lang="ar">الْمُعَامَلَةَ: بَدَلٌ مَنْصُوبٌ، وَعَلَامَةُ نَصْبِهِ الْفَتْحَةُ الظَّاهِرَةُ.</span><span class="rule-example-ru">الْمُعَامَلَةَ — بَدَلٌ в винительном падеже; показатель — явно выраженная фатха.</span></div></div></div></div>', 'Абсолютное дополнение и его заместитель стоят в винительном падеже. Окончание зависит от формы слова, а зависимые элементы разбираются по своей функции: как различительное слово, مُضَافٌ إِلَيْهِ или بَدَلٌ.', 'الْمَفْعُولُ الْمُطْلَقُ وَنَائِبُهُ مَنْصُوبَانِ، وَتَخْتَلِفُ عَلَامَةُ النَّصْبِ بِحَسَبِ صِيغَةِ الْكَلِمَةِ. وَإِذَا نَابَ عَنِ الْمَصْدَرِ عَدَدٌ أَوْ صِفَةٌ أَوْ اسْمُ إِشَارَةٍ، أُعْرِبَ النَّائِبُ مَفْعُولًا مُطْلَقًا، وَأُعْرِبَ مَا يَتْبَعُهُ بِحَسَبِ مَوْقِعِهِ.')
)
update public.rules as r
set title = incoming.title,
    content = incoming.content,
    rule_kind = 'rule',
    summary = incoming.summary,
    rule_ar = incoming.rule_ar
from incoming
where r.course_name = 'Мединский курс (Том 4)'
  and r.lesson_number = '11'
  and r.sort_order = incoming.sort_order;

delete from public.rule_sources
where rule_id in (
  select id from public.rules
  where course_name = 'Мединский курс (Том 4)' and lesson_number = '11'
);

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_4.pdf', 'الدَّرْسُ الْحَادِي عَشَرَ
الْمَفْعُولُ الْمُطْلَقُ
المفعولُ المطلقُ : مَصْدَرٌ يُذْكَرُ بعدَ فِعْلٍ من لَفْظِهِ .
أنواعه :
1- مُؤَكِّدٌ لفعله .             2- مُبَيَّنٌ لنوع الفعل .             3- مُبَيَّنٌ لعدد الفعل .
4- مصدرٌ نَائِبٌ عن فعله .
فمثال المؤكِّد لفعله : فهمت الدرس فهماً . أكلت أكلاً . نمتُ نوماً .
ومنه قوله تعالى : ﴿ وَكَلَّمَ اللَّهُ مُوسَى تَكْلِيمًا ﴾ .
ومثال الْمُبَيَّن للنوع : فهمت الدرس فهماً جيداً . أكلتُ أَكْلَ الجَائِعِ . فهمتُ المسألةَ فَهْمَ العُلماءِ . ومنه قوله تعالى : ﴿ وَتُحِبُّونَ الْمَالَ حُبًّا جَمًّا ﴾ .
وهذا النوع لا بُدَّ أن يكون ما بعد المصدر صِفةً ، أو مضافاً إليه ، كما ترى في الأمثلة .
ومثال الْمُبيَّن للعدد : طبعت الكتاب طَبْعَةً ، أو طَبْعَتَيْنِ ، أو طَبَعَاتٍ .
وسجدت لله سَجْدَةً ، أو سَجْدَتَيْنِ ، أو سَجَدَاتٍ .
ومثال النائب عن فعله : مهلاً ، وصبراً ، وحمداً ، وشكراً ؛ ونحو : سبحانَ اللهِ ،
ومَعَاذَ اللهِ ، ولَبَّيْكَ ، ونحو : سمعاً وطاعةً .', 45, 45, 1
from public.rules
where course_name = 'Мединский курс (Том 4)' and lesson_number = '11' and sort_order = 1;

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_4.pdf', 'حَذْفُ الْعَامِلِ
المفعول المطلق المؤكد لفعله : لا يجوز حذف عامله ؛ لأنه إنما جيء بالمصدر لتأكيد معنى عامله ، وتقويته .
أما المبين للنوع ، والعدد فيجوز حذف عاملهما بشرط الدلالة عليهما .
نحو : قُدُوماً مُبَارَكاً ، أي : قدمتَ قدوماً مباركاً ، ونحو : حَجًّا مَبْرُورًا ، أي :
حَجَجْتَ حَجًّا مَبْرُورًا ، ونحو : كم قراءةً قرأتَ الدرسَ ؟ قِرَاءَتَيْنِ ، أي : قرأته قراءتين ، ونحو :كم سجدةً لله سجدتَ ؟ سَجَدَاتٍ .', 46, 46, 1
from public.rules
where course_name = 'Мединский курс (Том 4)' and lesson_number = '11' and sort_order = 2;

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_4.pdf', 'النَّائِبُ عَنِ الْمَصْدَرِ
ينوب عن المصدر ما يدل عليه ، فَيُعْرَبُ مفعولا مطلقاً نائبا عن المصدر .
وينوب عن المصدر ما يلي :
1- ألفاظُ ( كُلٍّ ، وبَعْضٍ , و أَيٍّ ) مضافة إلى المصدر .
نحو : فهمتُ الدرسَ كُلَّ الْفَهْمِ . فهمتُ الدرسَ بَعْضَ الفهمِ . أَيَّ فَهْمٍ فهمتَ الدرسَ ؟
ومثلها : كَمْ , نحو : كم قراءةً قرأت الدرسَ ؟
2- صفةُ المصدرِ :
نحو : فهمتُ الدرسَ جيِّداً ، أي : فهماً جيداً ، ونحو : ساعدته أَحْسَنَ المساعدةِ .
3- عددُهُ :
نحو : زرتك ثلاثَ زياراتٍ ، ونحو : ضربته عشرين ضربةً . ومنه قوله تعالى: ﴿ فَاجْلِدُوا كُلَّ وَاحِدٍ مِنْهُمَا مِائَةَ جَلْدَةٍ ﴾ .
4- المصدرُ الَّذي يُلاَقِيهِ في الاشْتِقَاقِ :
نحو : تَبَسَّمْتُ ابْتِسَاماً ، أُحِبُّ اللهَ حُباًّ جَماًّ . ومنه قوله تعالى : ﴿ وَرَتِّلِ الْقُرْآنَ تَرْتِيلًا ﴾ .
فابتسام ليس مصدراً لـ ( تبسَّم ) ولكنهما يلتقيان في الاشتقاق فكلّ منهما مُشتق من الفعل ( بَسَمَ ) .
5- اسمُ المصدرِ ، وهو ما دلَّ على الْحَدَثِ كالمصدرِ، ولكنْ حروفُه أقلُّ من حروف المصدر, نحو : كَلَّمته كَلاَماً ، وصَلَّيت صَلاَةً , وقَبَّلْتُ ابني قُبْلَةً ، وَاغْتَسَلْتُ غُسْلاً ،
وأَعْطَيْتُهُ عَطَاءً . فالْكَلاَمُ ليس مصدراً أصلاً ، ولكنه يدل على الْحَدَث كالمصدر ، وحروفه أقلُّ من حروف المصدر الأصلي ( تَكَلُّماً ) ولا فِعْلَ ثُلاَثِيَّ له ؛ ولذلك سُمَّي اسم مصدر .
6- اسمُ الإشارةِ :
نحو : أتعامله تلك المعاملةَ ؟ ضربته هذا الضربَ لأنه كسلان .
7- الضَّميرُ العَائِدُ إلى المصدرِ :
نحو : قرأت قراءةً لم يقرأها غيري . ومنه قوله تعالى: ﴿ فَإِنِّي أُعَذِّبُهُ عَذَابًا لَا أُعَذِّبُهُ أَحَدًا مِنَ الْعَالَمِينَ ﴾ .
فالضمير في يقرأها عائد إلى المصدر ( قراءةً ) والضمير في ( لا أعذبه ) عائد إلى المصدر   ( عذاباً ) ولذلك يُعرب مفعولا مطلقاً .
8- مُرَادِفُهُ :
نحو : قُمْتُ وُقُوفاً . جَلَسْتُ قُعُوداً . فَرِحْتُ جَذَلاً . عِشْتُ حَيَاةً سعيدةً .
فالوقوف مُرَادِفٌ ومُمَاثِلٌ في المعنى لِلْقِيَام ... وهكذا الباقي .', 46, 47, 1
from public.rules
where course_name = 'Мединский курс (Том 4)' and lesson_number = '11' and sort_order = 3;

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_4.pdf', 'أقسام المصدر
1- مَصْدَرُ الْمَرَّة : يذكر لبيان عدد الفعل .
يُصَاغُ من الثُّلاثيِّ المجرَّدِ على وزن ( فَعْلَة ) نحو : سَجْدَة ، ورَكْعَة ، وضَرْبَة ، وأَكْلَة .
تقول : سجدتُ للهِ سَجْدَةً ، وركعتُ رَكْعَةً .
ويُصاغ من غير الثُّلاثي المجرَّد بزيادة ( تاء ) في آخر مصدره الأصلي .
نحو : كَبَّر          تَكْبِيرٌ        تَكْبِيرَةٌ. سَلَّمَ         تَسْلِيمٌ         تسليمةٌ .
إذا كان المصدر الأصلي مختوما ( بالتاء ) في أصل بنائه ذُكِرَ بعده ما يدل على العدد, ككلمة ( واحدة ) .
نحو : تَرْجَمْتُ الكتابَ تَرْجَمَةً واحدةً . اسْتَرَحْتُ اسْتِرَاحَةً واحدةً . أَقَمْتُ إِقَامَةً واحدةً .', 47, 48, 1
from public.rules
where course_name = 'Мединский курс (Том 4)' and lesson_number = '11' and sort_order = 4;

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_4.pdf', '2- مصدرُ الْهَيْئَةِ : يُذْكَرُ لبيانِ هَيْئَةِ الفعلِ وصفتِه .
يُصاغ من الثُّلاثي المجرَّد على وزن ( فِعْلَة ) نحو : إِكْلَة ، ومِشْيَة ، وجِلْسَة ، وقِتْلَة .
تقول : أكلتُ إِكْلَةَ الْجَائِعِ . مَشَيْتُ مِشْيَةَ الأسدِ . مَاتَ مِيتَةً حَسنَةً . ومنه قوله تعالى :
﴿ فَهُوَ فِي عِيشَةٍ رَاضِيَةٍ ﴾ لا يُصَاغ مصدرُ الهيئةِ من غيرِ الثُّلاثيِّ المجرَّدِ .', 48, 48, 1
from public.rules
where course_name = 'Мединский курс (Том 4)' and lesson_number = '11' and sort_order = 5;

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_4.pdf', '3- المصدرُ الْمِيمِيُّ : هو ما كانَ في أوَّلِه مِيمٌ زائدةٌ .
يُصاغ من الثلاثي المجرد على وزنين :
أ- مَفْعِل ، وذلك إذا كانَ معتلَّ الأوَّلِ صحيحَ الآخِرِ .
نحو : وَعَدَ : مَوْعِدٌ - وَقَفَ : مَوْقِفٌ - وَضَعَ : مَوْضِعٌ .
تقول : مَوْعِدُ اللهِ حَقٌّ ، أي : وَعْدُ اللهِ حقٌّ ؛ وتقول : مَوْقِفُكَ معي كان عظيماً ، أي :
وقوفك معي . ومنه قوله تعالى : ﴿ وَمَا كَانَ اسْتِغْفَارُ إِبْرَاهِيمَ لِأَبِيهِ إِلَّا عَنْ مَوْعِدَةٍ وَعَدَهَا إِيَّاهُ ﴾ .
ب- مَفْعَل : وذلك إذا لم يكن معتلَّ الأوَّلِ ، أي : ليس مِثَالاً .
نحو : ضَرَبَ : مَضْرَبٌ ، نَهَجَ : مَنْهَجٌ ، نَجَا : مَنْجَاةٌ ، قَالَ : مَقَالَةٌ .
تقول : نَهَجْتُ مَنْهَجَ الصَّالحين ، وسَلَكْتُ مَسْلَكَهُم ؛ وتقول : الصَّدْقُ مَنْجَاةٌ ، والكَذِبُ مَفْسَدَةٌ .
ويُصاغ من غير الثُّلاثي المجرَّد على زِنَةِ اسمِ المفعولِ (ميم مضمومة ، وفتح ما قبل
الآخر ) نحو : مُنْقَلَبٌ ، ومُمَزَّقٌ ، ومُخْتَلَفٌ ، ومُجْتَمَعٌ ، ومُسْتَقًى ، ومُدْخَل ، ومُخْرَج .
تقول : مُجْتَمَعُ الطُّلابِ خَيْرٌ ، أي : اجْتِمَاعُهُم ؛ وتقول : مُسْتَقَى الزَّرْعِ يُحْيِيهِ ، أي :
سَقْيُ الزَّرْع يُحْيِيه . ومنه قوله تعالى : ﴿ وَسَيَعْلَمُ الَّذِينَ ظَلَمُوا أَيَّ مُنْقَلَبٍ يَنْقَلِبُونَ ﴾
وقوله تعالى : ﴿ وَمَزَّقْنَاهُمْ كُلَّ مُمَزَّقٍ ﴾ .', 48, 49, 1
from public.rules
where course_name = 'Мединский курс (Том 4)' and lesson_number = '11' and sort_order = 6;

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_4.pdf', 'الإعراب : أكلتُ أكلاً .        ضربته ضربتين .        ضربته عشرين ضربةً .
فهمت جيِّداً .       فهمت كُلَّ الفهمِ .     مَهْلاً .     أتعامله هذهِ الْمُعَامَلَةَ .
أكلا : مفعول مطلق منصوب وعلامة نصبه الفتحة الظاهرة .
ضربتين : مفعول مطلق منصوب وعلامة نصبه الياء .
عشرين ضربةً : عشرين : مفعول مطلق نائب عن المصدر منصوب وعلامة نصبه الياء .
ضربةً : تمييز ذات منصوب وعلامة نصبه الفتحة الظاهرة .
جيِّداً : مفعول مطلق نائب عن المصدر منصوب وعلامة نصبه الفتحة الظاهرة .
كُلَّ الفهمِ : كلَّ : مفعول مطلق نائب عن المصدر منصوب وعلامة نصبه الفتحة
الظاهرة ، وهو مضاف .
الفهم : مضاف إليه مجرور وعلامة جرّه الكسرة الظاهرة .
مهلا : مفعول مطلق نائب عن فعله منصوب وعلامة نصبه الفتحة الظاهرة .
هذهِ المعاملةَ : هذه : اسم إشارة مبني على الكسر في محل نصب مفعول مطلق نائب
