do $migration$
declare
  updated_count integer;
  source_count integer;
begin
  select count(*) into updated_count
  from public.rules
  where course_name = 'Мединский курс (Том 4)' and lesson_number = '11' and rule_ar is not null and btrim(rule_ar) <> '';
  select count(*) into source_count
  from public.rule_sources rs
  join public.rules r on r.id = rs.rule_id
  where r.course_name = 'Мединский курс (Том 4)' and r.lesson_number = '11';
  if updated_count <> 7 or source_count <> 7 then
    raise exception 'Book 4 lesson 11 QA failed: rules %, sources %', updated_count, source_count;
  end if;
end $migration$;

